#if os(iOS)
import CoreGraphics
import Foundation
import ImageIO

/// macOS's own arrow cursor (`NSCursor.arrow`, macOS 27), drawn at 3x: what
/// the viewer shows before the Mac sends its cursor image, and for a Mac or
/// VNC server that sends none. Never a hand-drawn arrow: it has to look like
/// the Mac's. The image carries no shadow (macOS draws that itself).
enum MacArrowCursor {
    /// Size and hotspot in points (`NSCursor.arrow.image.size`, `.hotSpot`).
    static let points = CGSize(width: 28, height: 40)
    static let hotspot = CGPoint(x: 5, y: 5)

    static let image: CGImage? = {
        guard let data = Data(base64Encoded: png), let source = CGImageSourceCreateWithData(data as CFData, nil) else { return nil }
        return CGImageSourceCreateImageAtIndex(source, 0, nil)
    }()

    /// The PNG, 84x120 pixels (3x).
    private static let png = ""
}
#endif
